"use client";

import { motion, useReducedMotion, useScroll, useTransform } from "motion/react";
import { useRef } from "react";
import type { ComponentProps, ReactNode } from "react";

export type ParallaxPrimitiveProps = Omit<ComponentProps<typeof motion.div>, "children" | "ref"> & {
  children: ReactNode;
};

export function ParallaxPrimitive({ children, ...props }: ParallaxPrimitiveProps) {
  const target = useRef<HTMLDivElement>(null);
  const reduceMotion = useReducedMotion();
  const { scrollYProgress } = useScroll({ target, offset: ["start end", "end start"] });
  const travel = useTransform(scrollYProgress, [0, 1], [16.8, -16.8]);

  return (
    <motion.div
      {...props}
      ref={target}
      style={{ ...props.style, y: reduceMotion ? 0 : travel }}
    >
      {children}
    </motion.div>
  );
}
